SELECT DISTINCT a.*, CASE WHEN b.product_eng_name IS NOT NULL THEN 'Y' ELSE 'N' END AS first_buy, count(b.product_eng_name) AS product_buy_count, product_limit_count
FROM product_data a LEFT JOIN product_sale_log b ON a.product_eng_name = b.product_eng_name AND b.user_uuid = #{user_uuid}
GROUP BY a.product_eng_name

SELECT exp_booster_start_date, exp_booster_end_date
    FROM exp_booster_data
    WHERE user_uuid = #{user_uuid}
